import{_ as e,a,o as s,a6 as o}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Import Stats (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Import Stats","query":"query ImportStats($id: ID!) {\\n  adminSettingsDataTransferImportStats(id: $id) {\\n    _id\\n    code\\n    action\\n    state\\n    processedRowsCount\\n    invalidRowsCount\\n    errorsCount\\n    stats\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/settings/data-transfer/imports/13/stats\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminSettingsDataTransferImportStats\\": {\\n      \\"_id\\": 13,\\n      \\"code\\": \\"products\\",\\n      \\"action\\": \\"append\\",\\n      \\"state\\": \\"validated\\",\\n      \\"processedRowsCount\\": 0,\\n      \\"invalidRowsCount\\": 0,\\n      \\"errorsCount\\": 2,\\n      \\"stats\\": {\\n        \\"batches\\": {\\n          \\"total\\": 0,\\n          \\"completed\\": 0,\\n          \\"remaining\\": 0\\n        },\\n        \\"progress\\": 0,\\n        \\"summary\\": {\\n          \\"created\\": 0,\\n          \\"updated\\": 0,\\n          \\"deleted\\": 0\\n        }\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/data-transfer-imports/stats.md","filePath":"api/graphql-api/admin/settings/data-transfer-imports/stats.md","lastUpdated":1786429091000}'),r={name:"api/graphql-api/admin/settings/data-transfer-imports/stats.md"};function n(i,t,d,c,l,p){return s(),a("div",null,t[0]||(t[0]=[o('<h1 id="import-stats-graphql" tabindex="-1">Import Stats (GraphQL) <a class="header-anchor" href="#import-stats-graphql" aria-label="Permalink to &quot;Import Stats (GraphQL)&quot;">​</a></h1><p>Returns the current progress of an import <strong>without advancing it</strong>. Poll this between <a href="./start.html">start</a> / <a href="./link.html">link</a> / <a href="./">index</a> calls to drive a progress bar.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>adminSettingsDataTransferImportStats(id:)</code></td><td>Query</td><td>Read progress without running a stage</td></tr></tbody></table><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><ul><li><code>processedRowsCount</code> / <code>invalidRowsCount</code> / <code>errorsCount</code> — running counters.</li><li><code>stats.batches</code> — <code>total</code> / <code>completed</code> / <code>remaining</code> batch counts; <code>remaining</code> reaching <code>0</code> means the current stage has finished.</li><li><code>stats.progress</code> — percentage (0–100) of batches completed.</li><li><code>stats.summary</code> — created/updated/deleted record counts so far.</li></ul><h2 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h2><ul><li>The <code>id</code> argument is the <strong>stats IRI</strong> — append <code>/stats</code> to the import&#39;s resource path.</li><li><code>stats</code> is returned as a raw JSON object — query it bare (no sub-selection).</li><li>The job&#39;s entity is exposed as <code>code</code> (e.g. <code>products</code>), not <code>type</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative <code>id</code>. Replace it with the stats IRI of an import that exists in your store — use the <a href="./list.html"><code>adminSettingsDataTransferImports</code></a> query to discover valid ids.</p></div><p>Permission: <code>settings.data_transfer.imports.view</code>. All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const u=e(r,[["render",n]]);export{m as __pageData,u as default};
